CREATE TABLE selection_revision (id INTEGER PRIMARY KEY CHECK(id = 1), value INTEGER NOT NULL);
INSERT INTO selection_revision VALUES (1, 0);
CREATE TRIGGER selection_asset_added AFTER INSERT ON assets BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_asset_deleted AFTER DELETE ON assets BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_asset_changed AFTER UPDATE OF taken_at, missing_since, hidden, trashed_at, favourite, kind, place_id ON assets BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_tag_added AFTER INSERT ON asset_tags BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_tag_deleted AFTER DELETE ON asset_tags BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_tag_changed AFTER UPDATE ON asset_tags BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_face_added AFTER INSERT ON faces BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_face_deleted AFTER DELETE ON faces BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_face_changed AFTER UPDATE ON faces BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_album_added AFTER INSERT ON album_items BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_album_deleted AFTER DELETE ON album_items BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_album_changed AFTER UPDATE ON album_items BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_rule_changed AFTER UPDATE ON albums BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_event_added AFTER INSERT ON event_members BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_event_deleted AFTER DELETE ON event_members BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_event_changed AFTER UPDATE ON event_members BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_settings_added AFTER INSERT ON settings WHEN NEW.key = 'tag_confidence' BEGIN UPDATE selection_revision SET value = value + 1; END;
CREATE TRIGGER selection_settings_changed AFTER UPDATE ON settings WHEN NEW.key = 'tag_confidence' BEGIN UPDATE selection_revision SET value = value + 1; END;
